 function analysisHTML(){return researchResultsHTML(c,d,{identityError,region:'analysis'}).replace('<div id="research-simulation-root"></div>','').replace('<details class="research-card"><summary>Capital transition','<details class="research-card" data-annual-analysis="transition"><summary>Capital transition').replace('<details class="research-card"><summary>Original gross-to-net','<details class="research-card" data-annual-analysis="capital"><summary>Original gross-to-net').replace('<details class="research-card"><summary>Every annual','<details class="research-card" data-annual-analysis="calculations"><summary>Every annual');}
