 function bindActions(){root.querySelectorAll('[data-research-action]').forEach(button=>button.onclick=()=>{
  const action=button.dataset.researchAction;
  if(action==='undo-edit'){if(!editUndo.has(c.ticker))return;d=structuredClone(editUndo.get(c.ticker));editUndo.delete(c.ticker);activeEdit=null;save({stamp:false});render();return;}
  if(action==='legacy'){if(typeof document!=='undefined'){const picker=document.querySelector('#current-company');if(picker){picker.value=c.ticker;picker.onchange?.({target:picker});}document.querySelector('[data-tab="current"]')?.click();}return;}
  if(action==='export'){let output;try{output=exportResearchCase(d,c);}catch{output={originalResearchCase:c,retainedDraft:d,...(retainedRaw===null?{}:{rawSavedDraft:retainedRaw}),error:identityError||'Invalid edited inputs; no valuation exported.'};}if(output.operating){if(finite(output.timing.enterprise)){try{output.equityBridge=calculateResearchBridge(d,output.timing.enterprise,{...(d.bridgeInputs||{}),calculationDate:output.timing.date});}catch(e){output.equityBridge={status:'incomplete',equity:null,perShare:null,error:e.message};}}else output.equityBridge={status:'incomplete',equity:null,perShare:null,error:output.timing.message};}exportFile(`${c.ticker}-annual-research-${RESEARCH_VERSION}.json`,output);return;}
  if(action==='use-research'){try{useResearch();}catch(error){root.querySelector('#research-action-status').textContent=error.message;}return;}
  if(action==='undo'){if(!undo.has(c.ticker))return;editUndo.delete(c.ticker);const navigation=undoNavigation.get(c.ticker);d=structuredClone(undo.get(c.ticker));retainedRaw=undoRaw.get(c.ticker)??null;identityError=undoErrors.get(c.ticker)||restoreResearchDraft(d,c).error;undo.delete(c.ticker);undoRaw.delete(c.ticker);undoErrors.delete(c.ticker);undoNavigation.delete(c.ticker);write(undoKey(),'null');if(retainedRaw!==null)write(key(),retainedRaw);else save({stamp:false});render();if(navigation?.page==='renewed'&&navigation.previousAnnualTicker!==c.ticker)choose(navigation.previousAnnualTicker);if(navigation?.page)navigate(navigation.page);return;}
  if(action==='load'){editUndo.delete(c.ticker);write(undoKey(),'null');undoNavigation.delete(c.ticker);const loaded=loadAnnualResearchCase(d,c);undo.set(c.ticker,loaded.undo);undoRaw.set(c.ticker,retainedRaw);undoErrors.set(c.ticker,identityError);d=loaded.draft;identityError=null;retainedRaw=null;save();render();return;}
  if(action==='load-bridge'&&c.ticker==='LITE'&&!identityError){editUndo.delete(c.ticker);write(undoKey(),'null');undoNavigation.delete(c.ticker);undo.set(c.ticker,structuredClone(d));undoRaw.set(c.ticker,retainedRaw);undoErrors.set(c.ticker,identityError);d=structuredClone(d);d.bridgeInputs||={};const reviewed=researchBridgeDefinition('LITE');for(const field of reviewed.options)d.bridgeInputs[field.key]=field.default;d.bridgeReviewVersion=reviewed.bridgeVersion;save();render();return;}
  if(action==='normalize'){try{const next=terminalNormalizedDraft(d);editUndo.delete(c.ticker);write(undoKey(),'null');undoNavigation.delete(c.ticker);undo.set(c.ticker,structuredClone(d));undoRaw.set(c.ticker,retainedRaw);undoErrors.set(c.ticker,identityError);d=next;identityError=null;save();render();}catch(e){root.querySelector('#research-action-status').textContent=e.message;}return;}
 });}
